/bin/bash -lc "python - <<'EOF'
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
def redmask(t):
    f=d[t]; r,g,b=f[...,0],f[...,1],f[...,2]
    return (r>120)&(g<90)&(b<90)
m0=redmask(0)
for t in [10,20,30,40,50,60,70,80,95]:
    diff=(redmask(t)"'!=m0).sum()
    print('"'red mask diff 0 vs',t,':',diff)
# Track purple object centroid per frame
def pmask(t):
    f=d[t]; r,g,b=f[...,0],f[...,1],f[...,2]
    return (r>190)&(g>170)&(b>200)&(b>=r)
for t in range(0,96,4):
    m=pmask(t); ys,xs=np.where(m)
    print(t, 'n=',m.sum(),'cx=%.1f cy=%.1f'%(xs.mean(),ys.mean()), 'bbox',xs.min(),xs.max(),ys.min(),ys.max())
EOF"
